+async function listPorts(): Promise<{ path: string; friendlyName?: string }[]> {
+  const platform = os.platform();
+  if (platform === 'win32') {
+    // Windows: 获取 COM 端口
+    const { list } = await import('serialport');
+    const ports = await list();
+    return ports.map(p => ({ path: p.path, friendlyName: p.friendlyName }));
+  } else {
+    // Linux: ls /dev/ttyACM*
+    return new Promise((resolve) => {
+      exec('ls /dev/ttyACM*', (err, stdout) => {
+        if (err) return resolve([]);
+        const devices = stdout
+          .split('\n')
+          .filter(line => line.trim() !== '')
+          .map(path => ({ path }));
+        resolve(devices);
+      });
+    });
+  }
+}
+
+// 打开指定串口
+function connectDevice(path: string) {
+  if (port) {
+    port.close(() => {
+      port = null;
+      openPort(path);
+    });
+  } else {
+    openPort(path);
+  }
+}
